-- ── 5. FOREIGN KEYS (added last, order-independent) ─────────

ALTER TABLE bookings ADD CONSTRAINT fk_bookings_client FOREIGN KEY (client_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE bookings ADD CONSTRAINT fk_bookings_worker FOREIGN KEY (worker_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE green_coin_transactions ADD CONSTRAINT fk_gct_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE green_coins ADD CONSTRAINT fk_gc_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE greenloop_redemptions ADD CONSTRAINT fk_glred_reward FOREIGN KEY (reward_id) REFERENCES greenloop_rewards (id) ON DELETE CASCADE;
ALTER TABLE greenloop_redemptions ADD CONSTRAINT fk_glred_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

ALTER TABLE greenloop_reports ADD CONSTRAINT fk_glr_booking FOREIGN KEY (booking_id) REFERENCES bookings (id) ON DELETE SET NULL;
ALTER TABLE greenloop_reports ADD CONSTRAINT fk_glr_client FOREIGN KEY (client_id) REFERENCES users (id) ON DELETE CASCADE;
ALTER TABLE greenloop_reports ADD CONSTRAINT fk_glr_item FOREIGN KEY (item_id) REFERENCES greenloop_accepted_items (id) ON DELETE SET NULL;

ALTER TABLE hr_permissions ADD CONSTRAINT fk_hr_permissions_user FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

